def runs_of(cs):
    cs=set(cs); found=[]
    for (i,j) in sorted(cs):
        if (i,j-1) not in cs:
            k=j
            while (i,k+1) in cs: k+=1
            if k>j: found.append(('H',i,j,k))
    for (i,j) in sorted(cs,key=lambda t:(t[1],t[0])):
        if (i-1,j) not in cs:
            k=i
            while (k+1,j) in cs: k+=1
            if k>i: found.append(('V',j,i,k))
    return found

